export function evaluateMigration({operations=[],protectedTables=[],allowDestructive=false}={}){const violations=[];for(const op of operations){const kind=String(op.kind||'').toUpperCase();if(['DROP_TABLE','DROP_COLUMN','ALTER_TYPE_NARROW'].includes(kind)&&(!allowDestructive||protectedTables.includes(op.table)))violations.push({...op,reason:'DESTRUCTIVE_CHANGE'});if(kind==='ADD_NOT_NULL'&&!op.default&&!op.backfill)violations.push({...op,reason:'NOT_NULL_WITHOUT_BACKFILL'})}return {allow:violations.length===0,violations}}
